function makeAccumulator(start) {
  let total = start;
  return (amount) => {
    total += amount;
    return total;
  };
}

function makeGreeter(greeting) {
  return (name) => `${greeting}, ${name}`;
}

const wallet = makeAccumulator(10);
const bank = makeAccumulator(100);
console.log(`wallet: ${wallet(5)} ${wallet(5)}`);
console.log(`bank: ${bank(1)} ${bank(49)}`);
console.log(`wallet: ${wallet(30)}`);

const sayHi = makeGreeter("Hi");
console.log(sayHi("Ada"));
console.log(sayHi("Grace"));

example.code:
function* range(start, end, step) {
  for (let i = start; i < end; i += step) {
    yield i;
  }
}

function* powersOfTwo() {
  let value = 1;
  while (true) {
    yield value;
    value *= 2;
  }
}

console.log(`range: ${[...range(0, 10, 3)].join(", ")}`);

const powers = [];
for (const power of powersOfTwo()) {
  powers.push(power);
  if (powers.length === 6) {
    break;
  }
}
console.log(`powers: ${powers.join(", ")}`);

