practice.solution:
function* countdown(from) {
  for (let i = from; i >= 1; i--) {
    yield i;
  }
}

function* squares() {
  let n = 1;
  while (true) {
    yield n * n;
    n++;
  }
}

console.log(`countdown: ${[...countdown(5)].join(", ")}`);

const small = [];
for (const square of squares()) {
  if (square > 50) {
    break;
  }
  small.push(square);
}
console.log(`squares: ${small.join(", ")}`);
